 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            min_r = min(y for y, _ in cells)
            min_c = min(x for _, x in cells)
            shape = frozenset((y - min_r, x - min_c) for y, x in cells)
            objects.append((color, cells, shape))
    return objects


def transform(grid):
    out = [row[:] for row in grid]
    objects = _components(grid)
    exemplars = {}
    for color, _, shape in objects:
        if color != 1:
            exemplars.setdefault(shape, color)
    for color, cells, shape in objects:
        if color == 1 and shape in exemplars:
            for r, c in cells:
                out[r][c] = exemplars[shape]
    return out
